/**
 * The provider-agnostic boundary between Document Management and wherever
 * bytes actually live.
 *
 * `DocumentService` depends on this abstraction only. It never imports an
 * S3, Supabase, R2 or GCS SDK, and never sees a bucket, a region or a
 * credential — those are infrastructure concerns that belong to the adapter
 * bound in `StorageModule`, selected by `DOCUMENT_STORAGE_PROVIDER`.
 * Replacing the provider is a change to that one binding.
 *
 * `key` is always generated by `DocumentService` (organizationId / type
 * code / a fresh id) and never derived from a client-supplied filename —
 * that is what rules out path traversal from a crafted upload.
 *
 * Bytes handed to `upload()` are already the final ciphertext: encryption is
 * `IdentityCryptoService`'s job, one layer up, so a provider swap can never
 * accidentally change what is or is not encrypted at rest.
 */
export abstract class StoragePort {
  /** Named in `DocumentVersion.storageProvider`, so an old version stays
   *  resolvable by the adapter that wrote it even after a provider change. */
  abstract readonly providerName: string;

  abstract upload(
    key: string,
    data: Buffer,
    contentType: string,
  ): Promise<void>;

  abstract download(key: string): Promise<Buffer>;

  /** Idempotent — deleting an already-absent key is not an error. */
  abstract delete(key: string): Promise<void>;

  abstract exists(key: string): Promise<boolean>;
}
